INSERT INTO `email_templates` VALUES (1,'admin_reminder','[Aviso Interno] Vencimiento próximo: {{servicio}} — {{cliente}}','Hola {{admin}},\n\nTe notificamos que el siguiente servicio está próximo a vencer y requiere atención.\n\nPor favor revisa el panel de administración para coordinar la renovación con el cliente.\n\nEste aviso fue generado automáticamente por el sistema.','Cliente|{{cliente}}\nServicio|{{servicio}}\nVencimiento|{{fecha_vencimiento}}','admin_service_expiring','2026-03-11 21:46:44'),(2,'cliente_recordatorio','Recordatorio: tu servicio {{servicio}} vence el {{fecha_vencimiento}}','Estimado/a {{cliente}},\n\nTe informamos que el servicio contratado está próximo a su fecha de vencimiento.\n\nPara continuar disfrutando del servicio sin interrupciones, te recomendamos gestionar la renovación antes de la fecha indicada.\n\nSi tienes alguna pregunta, no dudes en contactarnos. Estamos a tu disposición.\n\nGracias por confiar en nosotros.','Servicio|{{servicio}}\nFecha de vencimiento|{{fecha_vencimiento}}','client_service_reminder','2026-03-11 21:46:44'),(3,'interno_tarea','Recordatorio de tarea: {{tarea}}','Hola {{admin}},\n\nEste es un recordatorio automático sobre una tarea interna pendiente que requiere tu atención.\n\nPor favor asegúrate de completarla antes de la fecha programada.\n\nSi ya fue atendida, puedes marcarla como completada en el sistema.','Administrador|{{admin}}\nTarea|{{tarea}}\nFecha programada|{{fecha_vencimiento}}','internal_task','2026-03-11 21:46:44'),(80,'cliente_ultimo_dia','Último día: tu servicio {{servicio}} vence hoy ({{fecha_vencimiento}})','Estimado/a {{cliente}},\n\nHoy es el último día de vigencia del servicio {{servicio}}.\n\nSi ya realizaste la renovación, puedes ignorar este mensaje.','Servicio|{{servicio}}\nVence hoy|{{fecha_vencimiento}}','','2026-03-14 20:25:51');
/*!40000 ALTER TABLE `email_templates` ENABLE KEYS */;
